('2ebaba38-064d-433c-8f31-0c6a7b802e91', '21feff02-016d-46e2-bb9d-c27495133b1b', '31. óra: A törtek szorzását alkalmazó feladatok megoldása', 'Törtrész kiszámítása és szöveges feladatok megoldása szorzással.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "bdba6134-b0c2-478b-ab22-ee865f767872", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "36fa47cb-0603-48a5-8f2d-11e23ff2bf83", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "3c867942-599c-4673-a815-c95f9efe5a29", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "6c1a5477-093a-4e1e-b2dd-68c5d610e2f3", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "18e6f2b4-ccca-4840-b56c-877d41826a5f", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "cb53fbc6-e303-4966-bc56-0c9c71065c0a", "text": "Igaz", "isCorrect": true}, {"id": "868173f3-17b8-400a-97a9-a3326ca36215", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "51edbd98-62c0-4dc1-bf97-8f8c97580c2d", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "3af6793c-d602-4661-a0ac-1302fc69eff4", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()),
('0e6e9279-37fa-4392-afff-7fb0636aee99', '21feff02-016d-46e2-bb9d-c27495133b1b', '32. óra: Osztás törttel', 'Törttel való osztás szabálya: szorzás a reciprokával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "e6304c49-2c5c-4907-bc1d-d9b2d89f8254", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "4095c822-64ae-4574-8a96-767ee9ba9015", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "f70e2986-9f59-408c-90d3-f73565f36e7a", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "09ec8e40-11e7-42b6-93ee-cbc472a3fa36", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "2dc52f1e-7e0b-415f-85b1-a294b42b2a74", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "0b0a0169-bbc4-466a-80c9-92699fa2f7d1", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "6e3c33a9-84a2-4b71-bdd5-3d834454815f", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "d0cb6898-7717-4810-90a9-e45387caf6af", "text": "8/15", "isCorrect": false}, {"id": "e0f27cad-8f87-4b8e-9cf1-76914e38621c", "text": "6/8", "isCorrect": false}, {"id": "b00c37a2-330c-4ccc-b6d8-9011d46fbbe0", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "18a00bd0-2404-4392-8ee9-015dd25c3344", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "b3cbf0e1-1468-4ab9-a5fc-9e12b1c429a8", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "ae2d3089-85a4-47e1-99d6-b077d90b6810", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "9fbbe257-1730-43b7-b705-c15122d9e777", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "12ad427e-5f36-471b-8b4d-a66d98dfabf9", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "79b06c93-54ff-49da-b64e-d5cdf0c4ab7f", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "2eb741fa-2ae5-445e-b673-4537ac3b3b55", "text": "Igaz", "isCorrect": true}, {"id": "88a6b5d4-37a6-4d0a-a869-8ec7b8d9f7ee", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7cc17d1a-6097-4776-b977-26691fe77620", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW()),
('4cc2c47e-a20a-4a37-bd54-c2343c1ef14e', '21feff02-016d-46e2-bb9d-c27495133b1b', '33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával', 'Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "e321cff3-6b1e-413f-929a-aec3ccfa4f20", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "ca7d412a-b441-4915-93f9-d7daa097ddd2", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "10b4d762-fc0d-4d3a-9016-7e9a4b45f56e", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "43b21149-c377-44df-b87a-dd5807834e25", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "d28916d9-46d8-4e69-be81-9fbbe693c3eb", "text": "Igaz", "isCorrect": true}, {"id": "773146e6-005f-40ca-a3e6-32843dc9e2dd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2f0ab8c5-8c81-4b51-8107-b865fdf0e82a", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "894e2457-41e0-4ac9-afb8-e163ace2179b", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "a2969417-bf4d-479a-ba90-86e55f3d847d", "text": "Igaz", "isCorrect": true}, {"id": "16d4dbb4-4d41-4091-849f-9e7b455def9b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "84a28a2d-33c6-4974-9ed9-b6a68ab69b9a", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()),
('e8f58d8e-610e-4121-ab37-43d3da5994dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '34. óra: Gyakorlóóra', 'A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "1653ddd6-5220-4009-91d5-d234ea0183b8", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "ec6a2a4e-96fa-44e0-978f-11b02d8e7639", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "dd4db50f-8606-4893-be4d-8c32c873b545", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "0ff7b624-f6e6-4652-ac39-f50ef08795b6", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "fd89102c-7f9e-4c57-a6a2-7fe967070166", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "7ac73fe5-a6fd-429f-b0dd-8a933c3cd7d0", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "bc2563f2-0e98-4a9f-afc3-7fc82f421ddd", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "136829e7-8bb5-4bbc-9b37-739717b10dde", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "9c44d5ba-1103-4503-8ed4-77aacfc2aac4", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "100cd9da-e693-47ec-8480-c92d45196d87", "text": "Igaz", "isCorrect": true}, {"id": "e9b6fafd-621a-4de5-9a8c-045ebbd719fa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0186a3d1-4431-4ff6-b232-b93c9e33d051", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "835b148d-3782-4287-8b67-9c2188345659", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "b38e3304-3a68-42ae-bcb1-51912652bbb2", "text": "1/5", "isCorrect": true}, {"id": "5a646b29-0aee-4547-9735