('591ddaaf-af86-4b64-af2a-d748589ec0af', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "566d9be0-dca4-4279-9f8c-21684aabce48", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "569a9099-942c-4c4e-9156-7f65d3f6df83", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "0d2a682f-60ba-44e1-b02f-cdf9240ab9ab", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "d8768eef-30ca-4253-b358-3f04cb0e681a", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "cee33bc8-6c0f-4180-a16d-21d004d0bdec", "text": "Igaz", "isCorrect": true}, {"id": "754764f3-c669-4744-a8ff-fe2bc165f863", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c7760c12-89c1-47a6-89a6-77bfc5b0ffa4", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "dd4a8b56-5df8-4a15-bf2a-94b118956dca", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "8558b3c2-2144-4b1e-88ea-3a2763eaa8cb", "text": "Igaz", "isCorrect": true}, {"id": "baa59497-4fcc-4d86-8c8b-3cc51bb839a2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c4576da-801e-45c7-842d-c5ff9190d152", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW()),
('4983bdf9-631e-46a1-a877-e8296c2dbc8e', '21feff02-016d-46e2-bb9d-c27495133b1b', '41. óra: Összetett műveletek, zárójelfelbontás', 'Műveleti sorrend, zárójelezés szabályai tizedes és közönséges törtekkel.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "8a77e81b-3023-4903-96df-fe2db3a55468", "text": "Mi a helyes műveleti sorrend?", "type": "multiple-choice", "options": [{"id": "6513433f-611c-4fdb-b2f6-93322814d68c", "text": "Zárójelben lévő műveletek -> szorzás/osztás balról jobbra -> összeadás/kivonás balról jobbra", "isCorrect": true}, {"id": "92acb4a8-4e0f-4d34-9863-a504b63be5d7", "text": "Mindig összeadással kezdünk", "isCorrect": false}, {"id": "a263e8c7-28a5-4a32-90a2-40ddcfa4a4a4", "text": "Balról jobbra haladunk művelet típustól függetlenül", "isCorrect": false}, {"id": "f4a3bd25-cc6d-45c0-9887-74d7b17a7805", "text": "Kivonással kezdünk", "isCorrect": false}], "timeLimit": 15}, {"id": "3005ff6c-5109-4e8a-a5c0-352dde0a2733", "text": "Mennyi 2 + 3 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "14"}, {"id": "c0e0a382-8083-44e5-9962-d9dbf6c81e9c", "text": "Mennyi (2 + 3) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "aa6f9774-d4ba-4810-812d-89da7e9ac593", "text": "Mennyi 10 - 2 * 3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "fb2daabb-6e6b-4823-95d3-7ca485dc7937", "text": "A zárójel megváltoztatja a műveletek elvégzésének megszokott sorrendjét.", "type": "true-false", "options": [{"id": "61701b8c-a850-4a92-9c55-bd2ebce9d6f4", "text": "Igaz", "isCorrect": true}, {"id": "7f8416e7-6cc9-4b3d-8e5c-39fa1c7aea3c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2b8bde10-9ebf-4fb9-bbd8-a71c77a6eb26", "text": "Mennyi 0,5 + 0,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "3e47229f-8e56-4341-a8e9-e3eaad8f0f91", "text": "Mennyi (0,5 + 0,5) * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()),
('390c24b9-8983-4ad1-ae66-78a969a8831a', '21feff02-016d-46e2-bb9d-c27495133b1b', '42. óra: Összetett műveletek, zárójelfelbontás gyakorlása', 'Gyakorlás feladatlapok és összetett kifejezések segítségével.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "14572b7c-1040-44c2-be66-b4d2e7c449e2", "text": "Mennyi 100 - (20 + 30)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "fb1aa534-7708-499d-b33e-7f3249f5e835", "text": "Mennyi 15 : 3 + 2 * 5? (5 + 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "2958839d-f610-4402-81f1-6220ef707291", "text": "Mennyi 0,2 * 5 + 0,8 : 2? (1 + 0,4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.4"}, {"id": "9623ccd7-6d29-468c-b2f7-ae28327f1815", "text": "A szorzás és az osztás egyenrangú műveletek, elvégzésük balról jobbra haladva történik.", "type": "true-false", "options": [{"id": "bef91731-58c2-4046-834f-7d756d730203", "text": "Igaz", "isCorrect": true}, {"id": "9a8d8d19-0dee-4347-b3a8-fac412d53d88", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9a6ebeb0-06e2-4526-898a-90a5f8bbeb05", "text": "Mennyi (1,2 + 0,8) * (3,5 - 1,5)? (2 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e4e9e0a5-79c8-4c48-a6bd-23f3c188948c", "text": "Ha a zárójel előtt minusz jel áll, a zárójel elhagyásakor a bent lévő tagok előjele az ellenkezőjére vált.", "type": "true-false", "options": [{"id": "f006639b-5a95-47ef-bba5-45f0fa588e3e", "text": "Igaz", "isCorrect": true}, {"id": "c2270d4b-054a-4946-98ed-e41950740dd5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ab9ed97-dcdc-4f3b-854a-fec99027fccd", "text": "Mennyi 50 - 5 * 8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()),
('8811e72c-1f02-4777-a4e3-d4d1b4d73fe6', '21feff02-016d-46e2-bb9d-c27495133b1b', '43. óra: Összefoglalás', 'A törtekről tanultak ismétlése, rendszerezése, algoritmusos gondolkodás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "922960ab-61ee-4067-8769-791fbe5c0380", "text": "Mennyi 3/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "75416124-f1e9-48c1-b028-d7bbc5bb0e59", "text": "3/5", "isCorrect": true}, {"id": "49689787-e54d-414a-ae8c-614e95c9f8aa", "text": "12/20", "isCorrect": false}, {"id": "a33fcc14-368a-4ffd-a650-7da62bf28b75", "text": "7/9", "isCorrect": false}, {"id": "2c49ce40-30d6-40b4-9e7a-2904400c8413", "text": "4/5", "isCorrect": false}], "timeLimit": 15}, {"id": "3b554322-6be8-4a81-a329-f89ba3190dc0", "text": "Mennyi 1/2 : 1/3? (1/2 * 3/1)", "type": "multiple-choice", "options": [{"id": "37c90f0f-73d3-4920-b38b-d6688a2c0c41", "text": "3/2 (1,5)", "isCorrect": true}, {"id": "a217e29f-05e8-4e28-98eb-cd04cfa72529", "text": "1/6", "isCorrect": false}, {"id": "2475d3f1-1aa2-4909-9778-64eeadec630b", "text": "2/3", "isCorrect": false}, {"id": "6abdf120-adef-4ab7-8f71-3c9e0c959050", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "635cf532-f544-48e9-9eff-557bd4945aa0", "text": "Mennyi 2,5 * 0,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "e9f619e9-4798-4ce4-9793-12762ef33888", "text": "Mennyi 6,4 : 0,8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "844212f7-02b9-4ea2-9c9b-87e37effe3f0", "text": "A 0,75 megegyezik a 3/4 közönséges tört értékével.", "type": "true-false", "options": [{"id": "db471437-496b-4499-abee-5e968bf2c4b8", "text": "Igaz", "isCorrect": true}, {"id": "bf9e5f9d-4345-4524-ae04-956927a2033c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3d888f56-fa79-4233-99a0-430c06a6388f", "text": "Mennyi 50-nek a 40%-a (vagy 2/5 része)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "f6f60b4c-4057-46b3-acdb-2c6607b0a64e", "text": "Melyik szám reciproka 0,5 (azaz 1/2)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()),
('dccf1eba-7989-4ea2-a93a-1adbc606b697', '21feff02-016d-46e2-bb9d-c27495133b1b', '44. óra: Feladatmegoldás', 'Gyakorló feladatok megbeszélése egyéni és csoportmunkában.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "32387511-1885-4249-988e-3714ef3ef401", "text": "Mennyi 0,75 + 1/4? (0,75 + 0,25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "93f12d17-d283-44ed-ac45-c07e34636955", "text": "Mennyi 1,5 - 3/4? (1,5 - 0,75)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.75"}, {"id": "ef0f3b45-cded-44a6-9382-4ed55c8f313f", "text": "Peti elköltötte a pénze 2/5-ét, majd a maradék 1/2-ét. A pénze hányadrésze maradt meg?", "type": "multiple-choice", "options": [{"id": "8a91d042-5371-4747-ac7f-723c176211db", "text": "3/10 (azaz 30%-a)", "isCorrect": true}, {"id": "be5535bb-3e31-4f59-8119-2df2db5a5c38", "text": "1/5", "isCorrect": false}, {"id": "ef1cd59d-4e1a-4277-a8da-e1095aed1011", "text": "1/2", "isCorrect": false}, {"id": "fa0d09af-d018-40c2-9900-73f8ac24630a", "text": "0", "isCorrect": false}], "timeLimit": 15}, {"id": "00fac468-cb89-4bd6-9854-7f06326c2e8d", "text": "Ha a számláló és a nevező megegyezik, a tört értéke 1.", "type": "true-false", "options": [{"id": "e1893b3c-587a-4746-9be8-85bf27bf2dae", "text": "Igaz", "isCorrect": true}, {"id": "79d42ad2-4156-4d13-8e66-fe0ee4fa7c0e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "99a26a85-52e3-4aa7-9ef9-57ce8f0342b8", "text": "Mennyi 0,8 * 2,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "22ae93b4-3d73-4f09-ada6-66f6a9aa15cc", "text": "Mennyi 9 : 0,3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "df9ab6e9-4a4e-4701-8464-d5056cae4f6a", "text": "A 0,125 megegyezik az 1/8 tört értékével.", "type": "true-false", "options": [{"id": "cbae0ff9-c637-4d2f-8489-6640720ad5f6", "text": "Igaz", "isCorrect": true}, {"id": "0a654229-be53-4f71-ba02-ab023211ddd3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('6aa21684-11da-49b7-9f4b-4d2147553efc', '21feff02-016d-46e2-bb9d-c27495133b1b', '45. óra: Játékos feladatok törtekkel', 'Társasjáték törtekkel, folyamatos tanári ellenőrzés és hibajavítás.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "57d06629-7b74-4125-8d98-b76dbe2d31c8", "text": "Melyik tört azonos értékű 4/12-vel?", "type": "multiple-choice", "options": [{"id": "cb326637-8487-4dd1-9d8d-3df84261d918", "text": "1/3", "isCorrect": true}, {"id": "1b86a5b5-cab6-4973-9f07-071e1581b594", "text": "1/4", "isCorrect": false}, {"id": "479b90dc-511e-415c-a5ca-e1141aabda8f", "text": "2/3", "isCorrect": false}, {"id": "7123c078-843e-4890-9e83-0c34600172d2", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "7d6fc33f-cfb3-47a8-8541-8f772daaa76d", "text": "Melyik tört azonos értékű 5/20-szal?", "type": "multiple-choice", "options": [{"id": "9cfef646-d9bb-4844-89d5-bcf7bea8e892", "text": "1/4", "isCorrect": true}, {"id": "63ef3518-731b-4b42-bcc7-d03655325d8a", "text": "1/5", "isCorrect": false}, {"id": "f417ec6a-7014-488c-a68c-cb469f7e2a76", "text": "2/5", "isCorrect": false}, {"id": "7e25fce5-dbd6-473c-ae23-e41fd5f8d489", "text": "1/2", "isCorrect": false}], "timeLimit": 15}, {"id": "c771ed2d-78fa-4b07-9c44-452473184948", "text": "Mennyi 0,6 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.3"}, {"id": "65d37756-f4e9-4203-8583-daed9e575113", "text": "Mennyi 0,4 : 0,2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "dbdad7e8-a124-48ba-a183-772d240ba7f7", "text": "A 0,5 nagyobb, mint a 0,45.", "type": "true-false", "options": [{"id": "71aae914-1555-4323-a33c-0eed3d88679b", "text": "Igaz (0,50 > 0,45)", "isCorrect": true}, {"id": "a3b2487b-f7a9-4a97-a8eb-3361b0ddf95c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "56749c11-4db9-430a-804d-17238abec987", "text": "Hány század van 0,3-ban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "0614453a-96cc-44ba-812e-9744b3cdda25", "text": "A törtek átírása tizedes tört alakba megkönnyíti az összehasonlítást.", "type": "true-false", "options": [{"id": "a148ccfa-761c-4563-90b3-3f8a5a0aaa5a", "text": "Igaz", "isCorrect": true}, {"id": "1f452d5d-93e5-4053-a721-3c0f96cf6b90", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
