('0252d98e-bfc6-46ae-b257-adccb628fce7', '21feff02-016d-46e2-bb9d-c27495133b1b', '50. óra: Egybevágóság', 'Egybevágó alakzatok felismerése, fedésbe hozása eltolással, forgatással, tükrözéssel.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "74dac841-62f8-47d2-9725-4235cd18acda", "text": "Mikor nevezünk két síkbeli alakzatot egybevágónak?", "type": "multiple-choice", "options": [{"id": "7fff5c9f-d187-4e25-8c29-d0d5573b6f62", "text": "Ha alakjuk és méretük pontosan megegyezik, mozgatással fedésbe hozhatók", "isCorrect": true}, {"id": "fc5d5a3c-b095-47cf-9885-1723ddeca669", "text": "Ha csak a színük egyezik", "isCorrect": false}, {"id": "5d53df06-03df-4412-8b0e-86bcc5ee3dba", "text": "Ha a területük 0", "isCorrect": false}, {"id": "e0745bb6-1ffd-4f3f-8f4e-a728f6786f37", "text": "Ha az egyik kétszer akkora", "isCorrect": false}], "timeLimit": 15}, {"id": "6fd2b787-330a-475c-a66e-25fd9986e6a3", "text": "Két egybevágó alakzat kerülete és területe megegyezik.", "type": "true-false", "options": [{"id": "f874353d-f27d-4fc4-b6eb-4c21f1853416", "text": "Igaz", "isCorrect": true}, {"id": "8934069d-d35c-47f5-a5ea-967830477c98", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5b74033f-a2b3-4fb6-b184-bba2e6d28b4f", "text": "Az eltolás, forgatás és tükrözés egybevágósági transzformációk.", "type": "true-false", "options": [{"id": "ef8b35cd-5485-446d-a4db-d223ef632629", "text": "Igaz", "isCorrect": true}, {"id": "8d2622c7-c246-4fa8-b46b-f38f2eba31ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7777793a-9f83-424d-9732-8dd7b57f5711", "text": "Egy alakzat eltolása során megváltozik-e az alakzat területe?", "type": "true-false", "options": [{"id": "1e0374a2-4908-415b-ada0-c0d9c47ffeb7", "text": "Igaz", "isCorrect": false}, {"id": "6ed70263-e045-47c1-b40f-1276c4252a52", "text": "Hamis (a terület nem változik)", "isCorrect": true}], "timeLimit": 15}, {"id": "5da17ed8-a223-4634-8739-90abcaeef2ec", "text": "Melyik állítás HAMIS