('edbe855d-033c-425a-a806-9db62e0c3d80', '21feff02-016d-46e2-bb9d-c27495133b1b', '53. óra: Szerkesztések', 'Alapszerkesztések: szakasz másolása, szög másolása, merőleges és párhuzamos állítása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "617357c7-e1a7-4690-8418-1f96e0f9a7d9", "text": "Milyen eszközt használunk körök és ívek rajzolásához szerkesztéskor?", "type": "multiple-choice", "options": [{"id": "ca212ad4-bf49-4a3c-b379-5f607fb26829", "text": "Körzőt", "isCorrect": true}, {"id": "4b5a3e44-1977-4e7a-acc0-070f11bbe74b", "text": "Szögmérőt", "isCorrect": false}, {"id": "cd6457e1-b030-4989-9c2f-accf72e60bb7", "text": "Radírt", "isCorrect": false}, {"id": "8abb6fee-a951-4138-b8f9-d67602784b19", "text": "Tollat", "isCorrect": false}], "timeLimit": 15}, {"id": "7749eba6-b0ab-425e-be8f-b86f7fab245f", "text": "Milyen vonalzót használunk a tiszta geometrikai szerkesztésekhez?", "type": "multiple-choice", "options": [{"id": "9b6e307d-24f8-43a2-9646-edf4f4041824", "text": "Beosztás nélküli (egyenes) vonalzót", "isCorrect": true}, {"id": "a894c8c6-a900-456a-8341-61533f3f5e53", "text": "Derékszögű vonalzót beosztással", "isCorrect": false}, {"id": "ac15a179-9892-4e34-aac3-35ec8420a793", "text": "Görbe vonalzót", "isCorrect": false}, {"id": "c36892b5-90c0-403c-b3b8-f7c2b1e30af1", "text": "Mérőszalagot", "isCorrect": false}], "timeLimit": 15}, {"id": "1f5d4332-8d6f-4d83-919a-a57ebf2e913d", "text": "Szakasz másolásakor körzővel mérjük fel a szakasz hosszát.", "type": "true-false", "options": [{"id": "16ed790e-1f37-4e03-8c05-25f48d9278fd", "text": "Igaz", "isCorrect": true}, {"id": "4a4264f2-0a3f-4ee2-8116-5adf380d85a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1a5fa109-70f8-46a5-ba02-64e42de34bd4", "text": "A szerkesztéseknél a körzőívek metszéspontjai adják meg a keresett pontokat.", "type": "true-false", "options": [{"id": "cf1ba6f6-471a-40db-a975-a433af461359", "text": "Igaz", "isCorrect": true}, {"id": "65098ea7-72be-462c-